/* From Uiverse.io by CheneyLin  - Tags: animation, progress bar, loader */
.__UIV_SCOPE__ .loader {
  position: absolute;
  border-radius: 10px;
  height: 20px;
  width: 320px;
  background-color: #aaa;
  animation: move-arrows 0.5s linear infinite;
  -webkit-animation: move-arrows 0.5s linear infinite;
  transform-origin: left;
  background-image: url("data:image/png;base64,");
  background-size: auto 100%;
}

@keyframes move-arrows {
  100% {
    background-position: 20px 0;
  }
}
@-webkit-keyframes move-arrows {
  100% {
    background-position: 20px 0;
  }
}
